  // Seeds are concatenated so the script's own text never contains one.
  const seed = (name, number) => 'SEED-' + name + '-' + number;
  document.querySelector('#password').value = seed('PW-LIVE', 4418);
  document.querySelector('#revealed').value = seed('REVEAL-LIVE', 8204);
  document.querySelector('#revealed').type = 'text';
  document.querySelector('#otp').value = seed('OTP-LIVE', 5522);
  document.querySelector('#otp').setAttribute('value', seed('OTP-LIVE', 5522));
})();

